cd /tmp/sv-f9beea850fc04f5c8ca8f2efc6a8c29b/advanced-multi-complexity && dotnet package list --format json 2>/dev/null | python3 -c "import sys,json; data=json.load(sys.stdin); json.dump(data,open('after-cpm-packages.json','w'),indent=2)" && python3 -c "
import json
before = json.load(open('baseline-packages.json'))
after = json.load(open('after-cpm-packages.json'))

def pkg_map(projects):
    m = {}
    for p in projects:
        name = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            key = (name, fw['framework'])
            for pkg in fw.get('topLevelPackages', []):
                m[(name, fw['framework'], pkg['id'])] = pkg['resolvedVersion']
    return m

b = pkg_map(before['projects'])
a = pkg_map(after['projects'])
all_keys = sorted(set(b) | set(a))
changes = []
unchanged = []
for k in all_keys:
    bv = b.get(k, 'N/A')
    av = a.get(k, 'N/A')
    if bv != av:
        changes.append((k[0], k[1], k[2], bv, av))
    else:
        unchanged.append((k[0], k[1], k[2], bv))

print('=== CHANGES ===')
if changes:
    for c in changes:
        print(f'{c[0]} ({c[1]}): {c[2]} {c[3]} -> {c[4]}')
else:
    print('None')
print()
print(f'=== UNCHANGED: {len(unchanged)} packages ===')"

